int ack(int num1, int num2)
{
    if (num1 == 0)
        return num2 + 1;
    else if (num1 > 0 && num2 == 0)
        return ack(num1 - 1, 1);
    else if (num1 > 0 && num2 > 0)
        return ack(num1 - 1, ack(num1, num2 - 1));
}

