category-factorial-variant.code:
#include <stdio.h>
static void sum_args(int a, int b) { printf("sum(args)=%d\n", a + b); }
static void sum_no_args(void) {
    int a = 3, b = 4;
    printf("sum(no args)=%d\n", a + b);
}
static unsigned fact_args(unsigned n) {
    unsigned result = 1;
    for (unsigned i = 1; i <= n; ++i) result *= i;
    return result;
}
static unsigned fact_no_args(void) { return fact_args(5); }
int main(void) {
    sum_args(3, 4);
    sum_no_args();
    printf("factorial(args)=%u\n", fact_args(5));
    printf("factorial(no args)=%u\n", fact_no_args());
    return 0;
}
